{
  "name": "区间图形标注对象",
  "name_en": "Interval Graphic Annotation",
  "manufacturer": "",
  "description": "这不是独立实验硬件，而是用于科学图像、谱图或数据视图中的区间图形标注对象。它通过起点和终点定义一维范围，常用于区域选择、测量、积分范围设定和交互式数据分析。",
  "description_en": "This is not a standalone laboratory instrument but a graphical annotation object used in scientific images, spectra, or data views. It defines a one-dimensional range using start and end points and is commonly used for region selection, measurement, integration range definition, and interactive data analysis.",
  "tag_hints": [
    "scientific image annotation",
    "ROI interval selection",
    "spectral range marking",
    "interactive graphics editing",
    "measurement region",
    "data visualization"
  ],
  "actions": [
    {
      "action_name": "auto-interval",
      "description": "获取或设置区间范围",
      "description_en": "Get or set the interval range."
    },
    {
      "action_name": "auto-reset_position",
      "description": "重置区间标注的位置",
      "description_en": "Reset the position of the interval annotation."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出标注的 MIME 数据字典",
      "description_en": "Export the annotation as a MIME data dictionary."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据读取标注",
      "description_en": "Read the annotation from MIME data."
    },
    {
      "action_name": "auto-read_properties_from_dict",
      "description": "从字典读取标注属性",
      "description_en": "Read annotation properties from a dictionary."
    },
    {
      "action_name": "auto-get_attributes",
      "description": "获取图形属性",
      "description_en": "Get the graphic attributes."
    },
    {
      "action_name": "auto-start",
      "description": "获取或设置区间起点",
      "description_en": "Get or set the interval start point."
    },
    {
      "action_name": "auto-end",
      "description": "获取或设置区间终点",
      "description_en": "Get or set the interval end point."
    },
    {
      "action_name": "auto-get_region",
      "description": "获取区间区域定义",
      "description_en": "Get the interval region definition."
    },
    {
      "action_name": "auto-test",
      "description": "测试指定点是否命中区间标注的可交互部分",
      "description_en": "Test whether a given point hits an interactive part of the interval annotation."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始拖拽编辑区间标注",
      "description_en": "Begin drag editing of the interval annotation."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束拖拽编辑区间标注",
      "description_en": "End drag editing of the interval annotation."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "调整区间标注的选定部分",
      "description_en": "Adjust a selected part of the interval annotation."
    },
    {
      "action_name": "auto-nudge",
      "description": "按给定位移微调区间标注",
      "description_en": "Nudge the interval annotation by a given offset."
    },
    {
      "action_name": "auto-read_interval",
      "description": "获取区间范围",
      "description_en": "Get the interval range."
    },
    {
      "action_name": "auto-write_interval",
      "description": "设置区间范围",
      "description_en": "Set the interval range."
    },
    {
      "action_name": "auto-validate_interval",
      "description": "验证区间范围",
      "description_en": "Validate the interval range."
    }
  ]
}

